UPDATE net_site_order_itemized
rule_code = #{ruleCode}, rule_name = #{ruleName}, unit_price = #{unitPrice}, min_bill_duration = #{minBillDuration}, max_bill_duration = #{maxBillDuration}, max_price = #{maxPrice}, pay_code = #{payCode}, only_code = #{onlyCode}, only_code_port = #{onlyCodePort}, total_duration = #{totalDuration}, per_use_duration = #{perUseDuration}, per_use_start_time = #{perUseStartTime}, update_time = NOW()
