mapper.select:
SELECT * FROM net_site_order_itemized

    AND rule_code = #{ruleCode}
    AND rule_name LIKE CONCAT('%', #{ruleName}, '%')
    AND pay_code = #{payCode}
    AND only_code = #{onlyCode}
    AND only_code_port = #{onlyCodePort}
    AND per_use_start_time >= #{startTime}
    AND per_use_start_time <= #{endTime}
    AND per_use_amount >= #{minAmount}
    AND per_use_amount <= #{maxAmount}

ORDER BY create_time DESC
LIMIT #{limit}

